Find the area of the shaded region bounded by $x=y^{2}+2$, the $y$-axis and the lines $y=0$ and $y=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.62cm, y=0.9cm]
\fill[gray!35, domain=0:2, variable=\y] (0,0) -- plot ({\y*\y+2},{\y}) -- (0,2) -- cycle;
\draw[->] (-1.7,0) -- (9.4,0) node[right] {$x$};
\draw[->] (0,-3.4) -- (0,3.4) node[above] {$y$};
\draw[thick, <->, domain=-2.5:2.5, smooth, samples=100, variable=\y] plot ({\y*\y+2},{\y});
\draw[dashed] (0,2) -- (6,2);
\node[left] at (0,2) {$2$};
\node[below] at (2,0) {$2$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $x=-2y$, the $y$-axis and the lines $y=0$ and $y=3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.55cm, y=0.75cm]
\fill[gray!35, domain=0:3, variable=\y] (0,0) -- plot ({-2*\y},{\y}) -- (0,3) -- cycle;
\draw[->] (-9.4,0) -- (9.4,0) node[right] {$x$};
\draw[->] (0,-4.6) -- (0,4.6) node[above] {$y$};
\draw[thick, <->, domain=-4:4, smooth, samples=100, variable=\y] plot ({-2*\y},{\y});
\draw[dashed] (0,3) -- (-6,3);
\node[right] at (0,3) {$3$};
\node[below] at (-6,0) {$-6$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=4x$, the $y$-axis and the lines $y=2$ and $y=8$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.5cm, y=0.42cm]
\fill[gray!35, domain=0.5:2, variable=\x] (0,2) -- plot ({\x},{4*\x}) -- (0,8) -- cycle;
\draw[->] (-1.8,0) -- (3.1,0) node[right] {$x$};
\draw[->] (0,-4.4) -- (0,11.4) node[above] {$y$};
\draw[thick, <->, domain=-1:2.5, smooth, samples=100, variable=\x] plot ({\x},{4*\x});
\draw[dashed] (0,8) -- (2,8);
\node[left] at (0,2) {$2$};
\node[left] at (0,8) {$8$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=x^{2}$ for $x\ge 0$, the $y$-axis and the lines $x=0$ and $x=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.6cm, y=0.8cm]
\fill[gray!35, domain=0:2, variable=\x] (0,0) -- plot ({\x},{\x*\x}) -- (0,4) -- cycle;
\draw[->] (-1.2,0) -- (3.1,0) node[right] {$x$};
\draw[->] (0,-1.2) -- (0,6.4) node[above] {$y$};
\draw[thick, ->, domain=0:2.4, smooth, samples=100, variable=\x] plot ({\x},{\x*\x});
\draw[dashed] (0,4) -- (2,4);
\draw[dashed] (2,0) -- (2,4);
\node[below] at (2,0) {$2$};
\node[left] at (0,4) {$4$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $x=y-2$, the $y$-axis and the lines $y=0$ and $y=6$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.7cm, y=0.6cm]
\fill[gray!35, domain=0:2, variable=\y] (0,0) -- plot ({\y-2},{\y}) -- (0,2) -- cycle;
\fill[gray!35, domain=2:6, variable=\y] (0,2) -- plot ({\y-2},{\y}) -- (0,6) -- cycle;
\draw[->] (-4.1,0) -- (5.6,0) node[right] {$x$};
\draw[->] (0,-2.4) -- (0,8.2) node[above] {$y$};
\draw[thick, <->, domain=-1.5:7, smooth, samples=100, variable=\y] plot ({\y-2},{\y});
\draw[dashed] (0,6) -- (4,6);
\node[right] at (0,2) {$2$};
\node[left] at (0,6) {$6$};
\node[below] at (-2,0) {$-2$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $x=y^{2}+1$, the $y$-axis and the lines $y=-1$ and $y=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.62cm, y=0.9cm]
\fill[gray!35, domain=-1:2, variable=\y] (0,-1) -- plot ({\y*\y+1},{\y}) -- (0,2) -- cycle;
\draw[->] (-1.7,0) -- (9.4,0) node[right] {$x$};
\draw[->] (0,-3.4) -- (0,3.4) node[above] {$y$};
\draw[thick, <->, domain=-2.5:2.5, smooth, samples=100, variable=\y] plot ({\y*\y+1},{\y});
\draw[dashed] (0,2) -- (5,2);
\draw[dashed] (0,-1) -- (2,-1);
\node[left] at (0,2) {$2$};
\node[left] at (0,-1) {$-1$};
\node[below] at (1,0) {$1$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=\sqrt{x+4}$, the $y$-axis and the lines $y=2$ and $y=3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.75cm, y=1.05cm]
\fill[gray!35, domain=2:3, variable=\y] (0,2) -- plot ({\y*\y-4},{\y}) -- (0,3) -- cycle;
\draw[->] (-5.6,0) -- (6.6,0) node[right] {$x$};
\draw[->] (0,-1.4) -- (0,4.4) node[above] {$y$};
\draw[thick, ->, domain=0:3.2, smooth, samples=100, variable=\y] plot ({\y*\y-4},{\y});
\draw[dashed] (0,3) -- (5,3);
\node[left] at (0,2) {$2$};
\node[left] at (0,3) {$3$};
\node[below] at (-4,0) {$-4$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $y=x^{3}-1$, the $y$-axis and the lines $x=0$ and $x=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.15cm, y=0.25cm]
\fill[gray!35, domain=0:2, variable=\x] (0,-1) -- plot ({\x},{\x*\x*\x-1}) -- (0,7) -- cycle;
\draw[->] (-3.1,0) -- (3.2,0) node[right] {$x$};
\draw[->] (0,-11.6) -- (0,10.6) node[above] {$y$};
\draw[thick, <->, domain=-2.1:2.1, smooth, samples=100, variable=\x] plot ({\x},{\x*\x*\x-1});
\draw[dashed] (0,7) -- (2,7);
\draw[dashed] (2,0) -- (2,7);
\node[below right] at (2,0) {$2$};
\node[left] at (0,7) {$7$};
\node[left] at (0,-1) {$-1$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region bounded by $x=y^{2}-9$, the $y$-axis and the lines $y=0$ and $y=4$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.36cm, y=0.62cm]
\fill[gray!35, domain=0:3, variable=\y] (0,0) -- plot ({\y*\y-9},{\y}) -- (0,3) -- cycle;
\fill[gray!35, domain=3:4, variable=\y] (0,3) -- plot ({\y*\y-9},{\y}) -- (0,4) -- cycle;
\draw[->] (-11.4,0) -- (13.4,0) node[right] {$x$};
\draw[->] (0,-5.4) -- (0,6.4) node[above] {$y$};
\draw[thick, <->, domain=-4.5:4.5, smooth, samples=100, variable=\y] plot ({\y*\y-9},{\y});
\draw[dashed] (0,4) -- (7,4);
\node[right] at (0,3) {$3$};
\node[left] at (0,4) {$4$};
\node[below] at (-9,0) {$-9$};
\end{tikzpicture}
[/tikz]
